cd /workspace && node -e "
const db = require('better-sqlite3')('./world.db');

// Find order
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%CCC96C%'\").all();
if (orders.length === 0) {
  console.log('No order found. Listing all order IDs:');
  const allOrders = db.prepare('SELECT order_id FROM orders').all();
  allOrders.forEach(o => console.log('  ' + o.order_id));
} else {
  const order = orders[0];
  console.log('=== ORDER ===');
  console.log(JSON.stringify(order, null, 2));

  const oid = order.order_id;

  console.log('\n=== ORDER ITEMS ===');
  const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(oid);
  items.forEach(i => console.log(JSON.stringify(i, null, 2)));

  console.log('\n=== ORDER FULFILLMENTS ===');
  const fulfillments = db.prepare('SELECT * FROM order_fulfillments WHERE order_id = ?').all(oid);
  fulfillments.forEach(f => console.log(JSON.stringify(f, null, 2)));

  console.log('\n=== ORDER PAYMENTS ===');
  const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(oid);
  payments.forEach(p => console.log(JSON.stringify(p, null, 2)));

  // Get user details
  if (order.customer_id) {
    console.log('\n=== CUSTOMER ===');
    const user = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.customer_id);
    if (user) console.log(JSON.stringify(user, null, 2));

    console.log('\n=== PAYMENT METHODS ===');
    const pms = db.prepare('SELECT * FROM rt_payment_methods WHERE user_id = ?').all(order.customer_id);
    pms.forEach(pm => console.log(JSON.stringify(pm, null, 2)));
  }
}
db.close();
"
